\begin{aligned}
\max\;& v \\
\text{s.t. }& \sum_{a \text{ out of } n} f_a - \sum_{a \text{ into } n} f_a =
  \begin{cases} v & n = s \\ -v & n = t \\ 0 & \text{otherwise} \end{cases} && \forall n && \text{(balance}_n) \\
& 0 \le f_a \le u_a && \forall a
\end{aligned}

smf = max_flow.SimpleMaxFlow()
for depot, shelf in SUPPLY.items():
    smf.add_arc_with_capacity(SOURCE, NODE[depot], shelf)
for (i, j), (_, cap) in ARCS.items():
    smf.add_arc_with_capacity(NODE[i], NODE[j], 0 if (i, j) in closed else cap)
for region, need in DEMAND.items():
    smf.add_arc_with_capacity(NODE[region], SINK, need)
if smf.solve(SOURCE, SINK) != smf.OPTIMAL:
    raise SystemExit("max flow failed")

\begin{aligned}
\min\;& \sum_{a} c_a\, f_a \\
\text{s.t. }& \sum_{a \text{ out of } n} f_a - \sum_{a \text{ into } n} f_a = b_n && \forall n && \text{(balance}_n) \\
& 0 \le f_a \le u_a && \forall a
\end{aligned}

if with_shelf:
    shelf = len(NAMES)                                   # one extra node: spares that stay put
    for depot, on_hand in SUPPLY.items():
        kept[depot] = smcf.add_arc_with_capacity_and_unit_cost(NODE[depot], shelf, on_hand, 0)
    smcf.set_node_supply(shelf, -(sum(SUPPLY.values()) - sum(DEMAND.values())))

